item.command:
/bin/bash -lc "python - <<'PY'
import zipfile, collections
for p in ['inputs/scogs_animals.zip','inputs/scogs_fungi.zip']:
 z=zipfile.ZipFile(p)
 c=collections.Counter()
 for n in z.namelist():
  if n.endswith('.mafft'):
   c[sum(x.startswith(b'>') for x in z.read(n).splitlines())]+=1
 print(p, sorted(c.items()))
PY"

